# Event sourcing + CQRS — bank account example
class BankAccount:
    def __init__(self, account_id):
        self.account_id = account_id
        self._events = []

    def _apply(self, event):
        self._events.append(event)

    def deposit(self, amount):
        self._apply({'type': 'Deposited', 'amount': amount})

    def withdraw(self, amount):
        self._apply({'type': 'Withdrawn', 'amount': amount})

    # CQRS read side: derive balance by replaying events
    def get_balance(self):
        balance = 0
        for e in self._events:
            if e['type'] == 'Deposited':
                balance += e['amount']
            elif e['type'] == 'Withdrawn':
                balance -= e['amount']
        return balance

    def get_history(self):
        return self._events

account = BankAccount('ACC-001')
account.deposit(1000)
account.withdraw(250)
account.deposit(500)

print(f'Event log: {account.get_history()}')
print(f'Current balance: {account.get_balance()}')
